		private SharedFilterFeedback(int preferredStage, double score, int observations) {
			this.preferredStage = preferredStage;
			this.score = score;
			this.observations = observations;
		}

		private static double score(long tested, long accepted, long elapsed, long avoided) {
			double rejected = tested - accepted;
			return (rejected + Math.max(0, avoided)) / Math.max(1.0, elapsed);
		}
